[CmdletBinding()]param([string]$HostName='localhost',[int]$Port=5432,[string]$Database='sigov',[string]$MaintenanceDatabase='postgres',[string]$AdminUser='postgres',[string]$AdminPassword=$env:PGPASSWORD,[string]$AppDbUser='sigov',[string]$AppDbPassword=$env:SIGOV_DB_PASSWORD,[string]$AdminLogin='admin',[string]$AdminEmail='admin@sigov.local',[string]$AdminPasswordApp=$env:SIGOV_BOOTSTRAP_ADMIN_PASSWORD,[string]$WebUrl='http://localhost:5000',[string]$ApiUrl='http://localhost:5001',[bool]$WorkerEnabled=$false,[switch]$RecreateDatabase,[switch]$ResetAdminPassword,[switch]$SkipDatabaseInstall,[switch]$SkipRuntimeUserProvision,[switch]$SkipBuild,[switch]$StartAfterSetup,[switch]$Force)
$ErrorActionPreference='Stop';$Root=Split-Path -Parent $PSScriptRoot;. "$PSScriptRoot/local-runtime-common.ps1";if($PSVersionTable.PSVersion.Major -lt 7){throw 'PowerShell 7+ obrigatório.'};foreach($t in 'dotnet','psql'){if(!(Get-Command $t -ErrorAction SilentlyContinue)){throw "$t não encontrado."}};$v=& psql --version;if($v -notmatch '(\d+)'){throw 'Não foi possível detectar PostgreSQL.'};if([int]$Matches[1] -lt 16){throw 'PostgreSQL/psql 16+ obrigatório.'}
function Secret{[Convert]::ToBase64String([Security.Cryptography.RandomNumberGenerator]::GetBytes(30)).Replace('+','A').Replace('/','B').TrimEnd('=')+'!a9'};$generatedDb=[string]::IsNullOrWhiteSpace($AppDbPassword);if($generatedDb){$AppDbPassword=Secret};$generatedAdmin=[string]::IsNullOrWhiteSpace($AdminPasswordApp);if($generatedAdmin){$AdminPasswordApp=Secret}
$envFile="$Root/.env.local";if((Test-Path $envFile)-and !$Force){Write-Host '.env.local existente será preservado; use -Force para sincronizar seus valores.';Import-SigovEnv $envFile;if($env:SIGOV_DB_PASSWORD){$AppDbPassword=$env:SIGOV_DB_PASSWORD}}else{if(!(Test-Path "$Root/.env.local.example")){throw '.env.local.example ausente.'};Copy-Item "$Root/.env.local.example" $envFile -Force;$values=@{SIGOV_DB_HOST=$HostName;SIGOV_DB_PORT=$Port;SIGOV_DB_NAME=$Database;SIGOV_DB_USER=$AppDbUser;SIGOV_DB_PASSWORD=$AppDbPassword;SIGOV_WEB_URL=$WebUrl;SIGOV_API_URL=$ApiUrl;SIGOV_MIGRATION_MODE='Disabled';SIGOV_RUN_MIGRATIONS='false';SIGOV_RUN_WORKER=$WorkerEnabled.ToString().ToLowerInvariant();SIGOV_BOOTSTRAP_ADMIN_LOGIN=$AdminLogin;SIGOV_BOOTSTRAP_ADMIN_EMAIL=$AdminEmail;SIGOV_BOOTSTRAP_ADMIN_PASSWORD=$AdminPasswordApp};$content=Get-Content $envFile;foreach($k in $values.Keys){if($content -match "^$k="){$content=$content -replace "^$k=.*","$k=$($values[$k])"}else{$content+="$k=$($values[$k])"}};$content|Set-Content $envFile}
$dir="$Root/artifacts/local-setup";New-Item -ItemType Directory -Force $dir|Out-Null;Start-Transcript "$dir/setup.log" -Force|Out-Null;$installed='reused';if(!$SkipDatabaseInstall){$env:PGPASSWORD=$AdminPassword;& "$PSScriptRoot/install-sigov-database.ps1" -HostName $HostName -Port $Port -Database $Database -MaintenanceDatabase $MaintenanceDatabase -User $AdminUser -Password $AdminPassword -AdminLogin $AdminLogin -AdminEmail $AdminEmail -AdminPassword $AdminPasswordApp -Recreate:$RecreateDatabase -ResetAdminPassword:$ResetAdminPassword;$installed=if($RecreateDatabase){'created'}else{'installed-or-reused'}};if(!$SkipRuntimeUserProvision){& "$PSScriptRoot/provision-sigov-db-user.ps1" -HostName $HostName -Port $Port -Database $Database -MaintenanceDatabase $MaintenanceDatabase -AdminUser $AdminUser -AdminPassword $AdminPassword -AppDbUser $AppDbUser -AppDbPassword $AppDbPassword};$diagnosis='OK';try{& "$PSScriptRoot/diagnose-sigov-database.ps1" -HostName $HostName -Port $Port -Database $Database -User $AppDbUser}catch{$diagnosis='Error'};$validation='OK';try{& "$PSScriptRoot/validate-sigov-runtime.ps1" -HostName $HostName -Port $Port -Database $Database -User $AppDbUser}catch{$validation='Error'};$build='Skipped';if(!$SkipBuild){dotnet build "$Root/sigov.sln" --configuration Release;if($LASTEXITCODE){$build='Error'}else{$build='OK'}};$result=[ordered]@{database=$installed;runtimeUser=if($SkipRuntimeUserProvision){'skipped'}else{'created-or-updated'};passwordSynchronized=$true;migrationMode='Disabled';apiUrl=$ApiUrl;webUrl=$WebUrl;workerEnabled=$WorkerEnabled;initialLogin=$AdminLogin;adminPassword=if($generatedAdmin){'generated (available only in .env.local)'}else{'preserved'};diagnosis=$diagnosis;runtimeValidation=$validation;build=$build;nextCommands=@('./scripts/start-local.ps1','./scripts/status-local.ps1','./scripts/check-runtime.ps1','./scripts/stop-local.ps1')};Write-SafeJson $result "$dir/setup-result.json";@('# Setup local SIGOV+','',"- Banco: $installed","- Runtime user: $($result.runtimeUser)",'- Senha: sincronizada (valor omitido)',"- MigrationMode: Disabled","- API: $ApiUrl","- Web: $WebUrl","- Worker: $WorkerEnabled","- Login inicial: $AdminLogin","- Senha admin: $($result.adminPassword)","- Diagnóstico: $diagnosis","- Validação: $validation","- Build: $build",'','## Próximos comandos','```powershell')+$result.nextCommands+@('```')|Set-Content "$dir/setup-report.md";Stop-Transcript|Out-Null;if($StartAfterSetup){& "$PSScriptRoot/start-local.ps1" -SkipBuild:$SkipBuild}
